/** Raw retained output (no cleaning) — test/UI helper. */
readOutputRaw(shellId: string): string | undefined {
  return this.shells.get(shellId)?.ring.readAll();
}

listForSession(sessionId: string): BgShell[] {
  return [...this.shells.values()]
    .filter((s) => s.sessionId === sessionId)
    .map((s) => this.toPublic(s));
}

list(): BgShell[] {
  return [...this.shells.values()].map((s) => this.toPublic(s));
}

/**
 * Read a shell's output. `mode=incremental` (default) returns text since the
 * agent's last read; `mode=all` returns the full retained buffer. Output is
 * ANSI-stripped and progress-folded, capped at the last READ_RETURN_CAP
 * chars. `expectSessionId`, when given, enforces session ownership.
 */
readOutput(
  shellId: string,
  mode: "incremental" | "all" = "incremental",
  expectSessionId?: string,
): ReadResult {
  const sh = this.shells.get(shellId);
  if (!sh) return { ok: false, error: `Unknown shell_id: ${shellId}` };
  if (expectSessionId !== undefined && sh.sessionId !== expectSessionId) {
    return { ok: false, error: `Unknown shell_id: ${shellId}` };
  }

  let rawSlice: string;
  let capped = false;
  if (mode === "all") {
    // Snapshot of the full retained buffer. This is explicitly a "show me the
    // tail" view — when it exceeds the cap we keep the LAST 16KB (most recent
    // output) and don't touch the incremental cursor.
    rawSlice = sh.ring.readAll();
    let text = cleanOutput(rawSlice);
    if (text.length > READ_RETURN_CAP) {
      text = text.slice(-READ_RETURN_CAP);
      capped = true;
    }
    return { ok: true, text, header: this.buildHeader(sh, capped, "all") };
  }

  // Incremental: deliver bytes since the agent's last read WITHOUT dropping
  // any. A single burst larger than the cap is paginated across successive
  // reads — we consume only the leading READ_RETURN_CAP *raw* bytes this call
  // and advance the absolute cursor by exactly that many, so the remainder is
  // returned next read. (Truncating to the trailing 16KB while advancing the
  // cursor to the end silently dropped the earliest bytes forever — #5.)
  //
  // Absolute stream cursor — survives ring wraparound (a window-relative
  // offset would silently skip new bytes once the window slides).
  const sliceBuf = sh.ring.sliceFromAbsolute(sh.agentReadOffset);
  // A live stream may currently end inside a character. Leave its bytes at
  // the absolute cursor until more arrive. Terminal/orphan snapshots consume
  // an incomplete EOF with normal replacement decoding instead of waiting.
  const availableBytes =
    sh.status === "running" || sh.status === "starting"
      ? completeUtf8PrefixLength(sliceBuf)
      : sliceBuf.length;
  let consumedBytes = availableBytes;
  let rawBuf = sliceBuf.subarray(0, availableBytes);
  if (rawBuf.length > READ_RETURN_CAP) {
    // Cap on RAW bytes (not cleaned length): cleanOutput only ever shrinks,
    // so the cleaned result of the first 16KB raw bytes is itself ≤ 16KB and
    // won't need a second truncation. Advancing the cursor by exactly
    // consumedBytes keeps the next read seamless.
    // Back the cut off to the last complete UTF-8 char boundary so a
    // multibyte char straddling the 16KB line isn't split into a `�` — and
    // so consumedBytes lands on a boundary and the next read resumes cleanly.
    // Guard against a pathological 0 (buffer starting mid-char) to guarantee
    // forward progress.
    const safeCut = utf8SafeCutLength(rawBuf, READ_RETURN_CAP) || READ_RETURN_CAP;
    rawBuf = rawBuf.subarray(0, safeCut);
    consumedBytes = safeCut;
    capped = true;
  }
  rawSlice = rawBuf.toString("utf8");
  sh.agentReadOffset += consumedBytes;

  const text = cleanOutput(rawSlice);
  return { ok: true, text, header: this.buildHeader(sh, capped, "incremental") };
}

/**
 * Build the status header line for a readOutput result. `mode` shapes the cap
 * note: `all` keeps the trailing 16KB (older output omitted from THIS view),
 * while incremental paginates (more output available on the next read).
 */

/**
 * Largest cut length ≤ `maxBytes` that does not split a multibyte UTF-8
 * character in `buf`. Used to paginate a large output burst without emitting a
 * `�` replacement char (and to keep the consumed-bytes cursor on a boundary so
 * the next read resumes cleanly).
 *
 * UTF-8: a continuation byte is 0b10xxxxxx (0x80–0xBF); a lead byte starts a
 * new character. If the byte at `maxBytes` is a continuation byte, we're mid
 * -character, so walk back to the last lead byte and cut there.
 */
export function utf8SafeCutLength(buf: Buffer, maxBytes: number): number {
  if (maxBytes >= buf.length) return buf.length;
  if (maxBytes <= 0) return 0;
  let cut = maxBytes;
  // Back off while the byte at the cut position is a UTF-8 continuation byte
  // (0x80–0xBF) — that means the char starting before `cut` isn't complete yet.
  while (cut > 0 && (buf[cut] & 0xc0) === 0x80) {
    cut--;
  }
  return cut;
}

    this.diskOk = false;
    this.fd = null;
  }
}

/** True if the disk mirror is usable (false → memory-only degraded mode). */
diskAvailable(): boolean {
  return this.diskOk;
}

write(chunk: Buffer): void {
  this.total += chunk.length;
  const combined = this.buf.length
    ? Buffer.concat([this.buf, chunk])
    : chunk;

  if (combined.length <= this.capBytes) {
    this.buf = combined;
    this.appendToDisk(chunk);
    return;
  }

  // Over cap: keep only the trailing capBytes.
  this.wrapped = true;
  this.buf = combined.subarray(combined.length - this.capBytes);
  this.rewriteDisk();
}

/** Whether any bytes have been discarded by wraparound. */
didWrap(): boolean {
  return this.wrapped;
}

/** The retained tail, decoded as UTF-8. */
readAll(): string {
  return this.buf.toString("utf8");
}

/** Current retained byte length (for the agent read offset math). */
byteLength(): number {
  return this.buf.length;
}

/** Bytes from `offset` (within the retained window) to the end. */
sliceFrom(offset: number): Buffer {
  const start = Math.max(0, Math.min(offset, this.buf.length));
  return this.buf.subarray(start);
}

/** Total bytes ever written to the logical stream (monotonic). Readers use
 *  this as their next cursor after a read. */
totalWritten(): number {
  return this.total;
}

/**
 * Bytes from an ABSOLUTE stream position to the current end. `absOffset` is
 * a value previously returned by {@link totalWritten}. If it points before
 * the retained window (the bytes were discarded by wraparound), returns the
 * whole window. If it's at/after the end, returns empty.
 */
sliceFromAbsolute(absOffset: number): Buffer {
  const windowStartAbs = this.total - this.buf.length; // abs position of buf[0]
  const rel = absOffset - windowStartAbs;
  const start = Math.max(0, Math.min(rel, this.buf.length));
  return this.buf.subarray(start);
}

close(): void {
  if (this.fd !== null) {
    try {
      fsyncSync(this.fd);
    } catch {
      /* best-effort */
    }
    try {
      closeSync(this.fd);

/**
 * Background-shell tools — BashOutput / KillShell / ListShells.
 *
 * Companions to `Bash(run_in_background=true)` (design §5.2–5.4). They
 * operate on the {@link BackgroundShellManager} (threaded via
 * `ctx.backgroundShells`, falling back to the process-local singleton).
 *
 * All three are session-scoped: a shell started in session A is invisible
 * and unreachable from session B (the manager enforces this; we pass
 * `ctx.sessionId` so cross-session ids report a plain "unknown shell_id"
 * rather than leaking another session's processes).
 */

import type { ToolContext } from "../context.js";
import type { ToolDefinition } from "../../types.js";
import { backgroundShellManager } from "../../runtime/background-shell.js";
import type { BackgroundShellManager } from "../../runtime/background-shell.js";

function managerFor(ctx?: ToolContext): BackgroundShellManager {
  return ctx?.backgroundShells ?? backgroundShellManager;
}

// ─── BashOutput ──────────────────────────────────────────────────────

export const bashOutputToolDef: ToolDefinition = {
  name: "BashOutput",
  description:
    "Read output from a background shell started via Bash(run_in_background=true). " +
    "Returns new output since your last read (incremental by default). ANSI colors and progress bars are stripped. " +
    "Use this only for an on-demand peek at a STILL-RUNNING process — you do NOT need to poll it to wait for " +
    "completion: when the background command finishes you are automatically woken with the result, so end your " +
    "turn instead of looping Sleep + BashOutput.",
  inputSchema: {
    type: "object",
    properties: {
      shell_id: {
        type: "string",
        description: "The shell_id returned by Bash(run_in_background=true).",
      },
      mode: {
        type: "string",
        enum: ["incremental", "all"],
        description:
          "incremental (default): output since your last read. all: the full retained buffer.",
      },
    },
    required: ["shell_id"],
  },
};

export async function bashOutputTool(
  args: Record<string, unknown>,
  ctx?: ToolContext,
): Promise<string> {
  const shellId = args.shell_id as string;
  if (!shellId) return "Error: shell_id is required";
  const mode = args.mode === "all" ? "all" : "incremental";
  const res = managerFor(ctx).readOutput(shellId, mode, ctx?.sessionId);
  if (!res.ok) return `Error: ${res.error}`;
  const body = res.text.length > 0 ? res.text : "(no new output)";
  return `${res.header}\n${body}`;
}
